import math

def pick(val, cands, tol=1e-9):
    hits = [s for v, s in cands if abs(v - val) < tol]
    assert len(hits) == 1, (val, hits)
    return hits[0]
def f(x):
    return math.sin(x) + math.cos(x) - 0.5
N = 200000
prods = []
for i in range(N):
    x0, x1 = 2 * math.pi * i / N, 2 * math.pi * (i + 1) / N
    if f(x0) * f(x1) < 0:
        lo, hi = x0, x1
        for _ in range(100):
            mid = (lo + hi) / 2
            if f(lo) * f(mid) <= 0:
                hi = mid
            else:
                lo = mid
        x = (lo + hi) / 2
        prods.append(math.sin(x) * math.cos(x))
assert len(prods) == 2 and abs(prods[0] - prods[1]) < 1e-9
print(pick(prods[0], [(-0.5, r"-\frac{1}{2}"), (-0.375, r"-\frac{3}{8}"), (-0.25, r"-\frac{1}{4}"), (0.375, r"\frac{3}{8}"), (0.5, r"\frac{1}{2}")]))

