import math

def pick(val, cands, tol=1e-9):
    hits = [s for v, s in cands if abs(v - val) < tol]
    assert len(hits) == 1, (val, hits)
    return hits[0]
def f(x):
    return math.sin(x) ** 2 + math.cos(3 * x)
pts = [0.1, 0.7, 1.9, 2.6, 4.2, 5.5]
def is_period(T):
    return all(abs(f(x + T) - f(x)) < 1e-9 for x in pts)
k = next(k for k in range(1, 601) if is_period(k * math.pi / 60))
print(pick(k * math.pi / 60, [(math.pi / 2, r"\frac{\pi}{2}"), (math.pi, r"\pi"), (5 * math.pi / 4, r"\frac{5\pi}{4}"), (3 * math.pi / 2, r"\frac{3\pi}{2}"), (2 * math.pi, r"2\pi")]))
